/**
 * Docsify 搜索插件 - 基于预生成索引（增强版）
 * 功能：进度显示、快捷键F、键盘导航
 */
(function () {
    var INDEX_PATH = 'search-index.json';
    var indexData = null;
    var selectedIndex = -1; // 当前选中的搜索结果索引，-1 表示无选中
    var results = []; // 当前搜索结果

    function mdToRoute(id) {
        if (!id) return id;
        return '#/' + id.replace(/^\.\//, '').replace(/\.md$/, '');
    }

    function escapeHtml(str) {
        return String(str).replace(/[&<>"']/g, function (m) {
            return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m];
        });
    }

    function getSnippet(content, query) {
        if (!content) return '';
        var idx = content.toLowerCase().indexOf(query.toLowerCase());
        if (idx === -1) return content.substring(0, 150) + '...';
        var start = Math.max(0, idx - 30);
        var end = Math.min(content.length, idx + query.length + 70);
        var s = content.substring(start, end);
        if (start > 0) s = '...' + s;
        if (end < content.length) s = s + '...';
        return s;
    }

    function highlightText(text, query) {
        if (!text || !query) return text || '';
        var terms = query.trim().split(/[\s\-，\\/]+/);
        terms.forEach(function (term) {
            if (!term) return;
            var re = new RegExp('(' + term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'gi');
            text = text.replace(re, '<em class="search-keyword">$1</em>');
        });
        return text;
    }

    function doSearch(query) {
        if (!query || !indexData) return [];
        var terms = query.trim().split(/[\s\-，\\/]+/);
        terms.unshift(query.trim());
        var res = [];
        for (var i = 0; i < indexData.length; i++) {
            var item = indexData[i];
            var title = (item.t || '').toLowerCase();
            var content = (item.c || '').toLowerCase();
            var score = 0, matched = false;
            for (var j = 0; j < terms.length; j++) {
                var t = terms[j].toLowerCase();
                if (!t) continue;
                if (title.indexOf(t) !== -1) { score += 3; matched = true; }
                if (content.indexOf(t) !== -1) { score += 2; matched = true; }
            }
            if (matched) {
                res.push({
                    url: mdToRoute(item.id),
                    title: highlightText(escapeHtml(item.t), query),
                    content: highlightText(escapeHtml(getSnippet(item.c, query)), query),
                    score: score
                });
            }
        }
        res.sort(function (a, b) { return b.score - a.score; });
        return res.slice(0, 50);
    }

    // ========== 进度显示 ==========
    function updateProgress(percent) {
        var el = document.querySelector('.search-progress');
        if (!el) return;
        if (percent >= 100) {
            el.textContent = '100%';
            el.classList.add('complete');
        } else {
            el.textContent = percent + '%';
            el.classList.remove('complete');
        }
    }

    // 心跳进度：模拟加载过程
    var progressTimer = null;
    var currentProgress = 0;

    function startProgress() {
        currentProgress = 0;
        updateProgress(0);
        progressTimer = setInterval(function () {
            if (currentProgress < 15) {
                currentProgress++;
                updateProgress(currentProgress);
            } else {
                clearInterval(progressTimer);
            }
        }, 200);
    }

    function stopProgress() {
        if (progressTimer) {
            clearInterval(progressTimer);
            progressTimer = null;
        }
        currentProgress = 100;
        updateProgress(100);
    }

    // ========== 索引加载 ==========
    function loadIndex(callback) {
        if (indexData) { callback(indexData); return; }
        startProgress();
        var xhr = new XMLHttpRequest();
        xhr.open('GET', INDEX_PATH, true);
        xhr.onload = function () {
            if (xhr.status === 200) {
                try { indexData = JSON.parse(xhr.responseText); } catch (e) { indexData = []; }
            } else { indexData = []; }
            stopProgress();
            callback(indexData);
        };
        xhr.onerror = function () {
            indexData = [];
            stopProgress();
            callback(indexData);
        };
        xhr.send();
    }

    // ========== 搜索结果渲染 ==========
    function renderResults(query, resultsPanel, clearBtn) {
        if (!resultsPanel) return;
        selectedIndex = -1;
        if (!query) {
            resultsPanel.classList.remove('show');
            resultsPanel.innerHTML = '';
            clearBtn.classList.remove('show');
            results = [];
            return;
        }
        clearBtn.classList.add('show');
        loadIndex(function (index) {
            results = doSearch(query);
            var html = '';
            results.forEach(function (item, i) {
                html += '<div class="matching-post" data-index="' + i + '">' +
                    '<a href="' + item.url + '">' +
                    '<h2>' + item.title + '</h2>' +
                    '<p>' + item.content + '</p>' +
                    '</a></div>';
            });
            resultsPanel.innerHTML = html || '<p class="empty">没有找到相关结果</p>';
            resultsPanel.classList.add('show');
        });
    }

    // ========== 键盘导航 ==========
    function updateSelection(resultsPanel) {
        var items = resultsPanel.querySelectorAll('.matching-post');
        items.forEach(function (el, i) {
            if (i === selectedIndex) {
                el.classList.add('active');
                el.scrollIntoView({ block: 'nearest' });
            } else {
                el.classList.remove('active');
            }
        });
    }

    function isInputFocused() {
        var el = document.activeElement;
        if (!el) return false;
        var tag = el.tagName;
        return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || el.isContentEditable;
    }

    // ========== 样式注入 ==========
    function injectStyles() {
        if (document.getElementById('search-index-style')) return;
        var style = document.createElement('style');
        style.id = 'search-index-style';
        style.textContent =
            '.sidebar { padding-top: 0; }\n' +
            '.search { margin-bottom: 20px; padding: 6px; border-bottom: 1px solid #eee; }\n' +
            '.search .input-wrap { display: flex; align-items: center; }\n' +
            '.search .results-panel { display: none; }\n' +
            '.search .results-panel.show { display: block; }\n' +
            '.search input { outline: none; border: none; width: 100%; padding: 0.6em 7px; font-size: inherit; border: 1px solid transparent; }\n' +
            '.search input:focus { box-shadow: 0 0 5px var(--theme-color, #42b983); border: 1px solid var(--theme-color, #42b983); }\n' +
            '.search input::-webkit-search-decoration, .search input::-webkit-search-cancel-button, .search input { -webkit-appearance: none; -moz-appearance: none; appearance: none; }\n' +
            '.search input::-ms-clear { display: none; height: 0; width: 0; }\n' +
            '.search .search-progress { font-size: 12px; color: #999; white-space: nowrap; margin-left: 4px; user-select: none; }\n' +
            '.search .search-progress.complete { color: var(--theme-color, #42b983); font-weight: 600; }\n' +
            '.search .clear-button { cursor: pointer; width: 36px; text-align: right; display: none; }\n' +
            '.search .clear-button.show { display: block; }\n' +
            '.search .clear-button svg { transform: scale(.5); }\n' +
            '.search h2 { font-size: 17px; margin: 10px 0; }\n' +
            '.search a { text-decoration: none; color: inherit; }\n' +
            '.search .matching-post { border-bottom: 1px solid #eee; }\n' +
            '.search .matching-post:last-child { border-bottom: 0; }\n' +
            '.search .matching-post.active { background: rgba(66, 185, 131, 0.1); }\n' +
            '.search p { font-size: 14px; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }\n' +
            '.search p.empty { text-align: center; }\n';
        document.head.appendChild(style);
    }

    // ========== 注入搜索框 ==========
    function getSidebarContainer() {
        var sidebarNav = document.querySelector('.sidebar-nav');
        if (sidebarNav) return sidebarNav.parentElement;
        return null;
    }

    function injectSearchBox() {
        if (document.querySelector('div.search')) return;

        injectStyles();

        var container = getSidebarContainer();
        if (!container) return;

        var searchHTML =
            '<div class="input-wrap">' +
            '<input type="search" value="" aria-label="Search text" placeholder="搜索（F）" />' +
            '<span class="search-progress">0%</span>' +
            '<div class="clear-button"><svg width="26" height="24">' +
            '<circle cx="12" cy="12" r="11" fill="#ccc"/>' +
            '<path stroke="white" stroke-width="2" d="M8.25,8.25,15.75,15.75"/>' +
            '<path stroke="white" stroke-width="2" d="M8.25,15.75,15.75,8.25"/>' +
            '</svg></div></div>' +
            '<div class="results-panel"></div>';

        var searchEl = document.createElement('div');
        searchEl.className = 'search';
        searchEl.innerHTML = searchHTML;

        container.insertBefore(searchEl, container.firstChild);

        var searchInput = searchEl.querySelector('input');
        var resultsPanel = searchEl.querySelector('.results-panel');
        var clearBtn = searchEl.querySelector('.clear-button');

        // 阻止搜索区域的事件冒泡（避免触发 Docsify 路由）
        searchEl.addEventListener('click', function (e) {
            if (['A', 'H2', 'P', 'EM'].indexOf(e.target.tagName) === -1) {
                e.stopPropagation();
            }
        });

        // 搜索输入防抖
        var debounceTimer = null;
        searchInput.addEventListener('input', function () {
            var query = this.value.trim();
            clearTimeout(debounceTimer);
            debounceTimer = setTimeout(function () {
                renderResults(query, resultsPanel, clearBtn);
            }, 200);
        });

        // 清除按钮
        clearBtn.addEventListener('click', function () {
            searchInput.value = '';
            renderResults('', resultsPanel, clearBtn);
            searchInput.focus();
        });

        // 键盘导航
        searchInput.addEventListener('keydown', function (e) {
            // 方向键和回车需要有搜索结果才生效
            if (!resultsPanel.classList.contains('show') || results.length === 0) return;

            if (e.key === 'ArrowDown') {
                e.preventDefault();
                selectedIndex = Math.min(selectedIndex + 1, results.length - 1);
                updateSelection(resultsPanel);
            } else if (e.key === 'ArrowUp') {
                e.preventDefault();
                selectedIndex = Math.max(selectedIndex - 1, -1);
                updateSelection(resultsPanel);
            } else if (e.key === 'Enter') {
                e.preventDefault();
                if (selectedIndex >= 0 && selectedIndex < results.length) {
                    window.location.hash = results[selectedIndex].url;
                    searchInput.blur();
                }
            }
        });

        // 预加载索引（显示进度）
        loadIndex(function () {});
    }

    // ========== 全局快捷键 ==========
    document.addEventListener('keydown', function (e) {
        if (e.ctrlKey || e.altKey || e.metaKey) return;

        // ESC：重置搜索框（等同于点击关闭按钮 x）
        if (e.key === 'Escape') {
            var input = document.querySelector('.search input');
            var clearBtnEl = document.querySelector('.search .clear-button');
            if (input && clearBtnEl) {
                clearBtnEl.click();
            }
            return;
        }

        // F：聚焦搜索框
        if (!isInputFocused() && (e.key === 'f' || e.key === 'F')) {
            e.preventDefault();
            var input = document.querySelector('.search input');
            if (input) {
                input.focus();
                input.select();
            }
        }
    });

    // ========== 初始化 ==========
    var attempts = 0;
    var timer = setInterval(function () {
        attempts++;
        injectSearchBox();
        if (document.querySelector('div.search') || attempts >= 30) {
            clearInterval(timer);
        }
    }, 1000);

    window.addEventListener('load', function () {
        injectSearchBox();
    });
})();
